import{_ as n,o as a,c as i,a5 as e}from"./chunks/framework.CsGesDJn.js";const k=JSON.parse('{"title":"Kịch bản nghiệm thu","description":"","frontmatter":{},"headers":[],"relativePath":"feature/package-driven-campaign-tasks/test.md","filePath":"feature/package-driven-campaign-tasks/test.md"}'),h={name:"feature/package-driven-campaign-tasks/test.md"};function r(c,t,d,g,s,o){return a(),i("div",null,[...t[0]||(t[0]=[e('<h1 id="kich-ban-nghiem-thu" tabindex="-1">Kịch bản nghiệm thu <a class="header-anchor" href="#kich-ban-nghiem-thu" aria-label="Permalink to &quot;Kịch bản nghiệm thu&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Kịch bản</th><th>Kết quả</th></tr></thead><tbody><tr><td>Owner tạo gói mẫu, Manager tạo gói custom, Client chọn gói mẫu</td><td>Đúng quyền từng luồng</td></tr><tr><td>Chọn bài đăng 3, event 1</td><td>Mỗi dịch vụ một dòng, mở đúng nhóm trường; API từ chối trùng, livestream và số lượng không hợp lệ với gói mới</td></tr><tr><td>Hai bên duyệt chốt package</td><td>Một DRAFT, đúng 4 task lớn, từng task truy về dòng cam kết</td></tr><tr><td>Duyệt đồng thời hoặc lỗi trong transaction tạo campaign/task</td><td>Một campaign, đủ task; khi transaction thất bại phải rollback, không để dữ liệu ghi dở</td></tr><tr><td>Duyệt một bên rồi cả hai, sau đó bắt đầu campaign</td><td>DRAFT → APPROVED → IN_PROGRESS đúng luồng; trước IN_PROGRESS thành viên không thể bắt đầu task kể cả gọi API trực tiếp</td></tr><tr><td>Manager sửa một task, rồi hủy một task lớn</td><td>Snapshot không đổi; chỉ Manager được hủy; không sinh thay thế</td></tr><tr><td>Client yêu cầu thêm qua Content Request</td><td>Task mới không tính vào số lượng gốc</td></tr><tr><td>Manager thêm subtask; đổi assignee cha</td><td>Chặn tầng thứ hai; supervisor mặc định đổi theo, override giữ nguyên</td></tr><tr><td>Thành viên, supervisor, Manager và Client thao tác</td><td>Đúng quyền đọc/chuyển trạng thái; supervisor và Manager có thể chuyển thẳng Done/Cancelled; Client chỉ xem</td></tr><tr><td>Gửi duyệt cha khi có subtask mở, rồi đưa tất cả về Done/Cancelled</td><td>Lần đầu bị chặn và có thông tin xử lý; lần sau đi qua approval circle hiện có</td></tr><tr><td>Đóng campaign sau khi task lớn đạt điều kiện hiện tại</td><td>Đối chiếu đúng tập task gốc; subtask không bị tính như task đầu ra</td></tr><tr><td>Tất cả task lớn từ package đã kết thúc nhưng còn Content Request đã nhận chưa hoàn thành</td><td>Chặn đóng campaign và chỉ rõ request đang chặn</td></tr><tr><td>Task liên kết của mọi Content Request đã nhận đều Done hoặc Cancelled</td><td>Đóng được campaign nếu các điều kiện còn lại đều đạt</td></tr><tr><td>Kiểm tra toàn bộ form, vi/en, light/dark, responsive</td><td>Mọi trường có hỗ trợ theo kiểu dữ liệu, gợi ý chỉnh được và giao diện giữ khả năng thao tác</td></tr></tbody></table><h2 id="kiem-chung-seed" tabindex="-1">Kiểm chứng seed <a class="header-anchor" href="#kiem-chung-seed" aria-label="Permalink to &quot;Kiểm chứng seed&quot;">​</a></h2><p>Đã chạy CLI seed-postgres và seed-mongo trên DB test riêng, kiểm tra 275 tài liệu Mongo không vi phạm schema. Kiểm tra quick-login có 5 task, 5 subtask và 2 post liên kết. Chạy lại CLI giữ nguyên số lượng theo seed marker; chạy lại quick-login trên workspace đã tồn tại bị từ chối để tránh ghi đè workflow. Các kết quả này không thay cho kiểm tra giao diện trên trình duyệt.</p>',4)])])}const l=n(h,[["render",r]]);export{k as __pageData,l as default};
